CONF = ("import math, random\n\n"
        "rng = random.Random(7)\n\n"
        "def model(x):\n"
        "    return 2 * x + 1                      # оқытылған регрессия (дәл емес)\n\n"
        "def sample(n):\n"
        "    xs = [rng.uniform(0, 10) for _ in range(n)]\n"
        "    return [(x, 2.2 * x + 0.5 + rng.gauss(0, 1.5)) for x in xs]\n\n"
        "alpha = 0.1                               # 90% қамту мақсаты\n"
        "calib = sample(150)\n"
        "scores = sorted(abs(y - model(x)) for x, y in calib)\n"
        "n = len(scores)\n"
        "k = math.ceil((n + 1) * (1 - alpha))      # конформдық квантиль индексі\n"
        "q = scores[k - 1]\n"
        "print(f'калибрлеу: n = {n}, квантиль q = {q:.3f}')\n\n"
        "test = sample(800)\n"
        "covered = sum(model(x) - q <= y <= model(x) + q for x, y in test) / len(test)\n"
        "print(f'интервал [ŷ − q, ŷ + q] тестте қамтыды: {covered:.1%} (кепілдік ≥ {1 - alpha:.0%})')\n"
        "print(f'мысал: x = 4 -> болжам {model(4):.1f}, 90% интервал [{model(4) - q:.2f}, {model(4) + q:.2f}]')\n\n"
        "# Кепілдік калибрлеу жиындары бойынша ОРТАША: 15 түрлі калибрлеу жиыны\n"
        "covs = []\n"
        "for _ in range(15):\n"
        "    sc = sorted(abs(y - model(x)) for x, y in sample(n))\n"
        "    qq = sc[k - 1]\n"
        "    covs.append(sum(abs(y - model(x)) <= qq for x, y in sample(200)) / 200)\n"
        "print(f'15 калибрлеу бойынша: орташа {sum(covs) / 15:.1%}, ең азы {min(covs):.1%}, ең көбі {max(covs):.1%}')")

