DP = ("import math, random\n\n"
      "rng = random.Random(7)\n\n"
      "def laplace(scale):\n"
      "    u = rng.random() - 0.5\n"
      "    return -scale * math.copysign(1, u) * math.log(1 - 2 * abs(u))\n\n"
      "def private_count(true_count, epsilon):\n"
      "    return true_count + laplace(1 / epsilon)        # санауыштың сезімталдығы 1\n\n"
      "true = 37          # сыныпта көмекке мұқтаж оқушылар саны\n"
      "for eps in (0.1, 1.0, 5.0):\n"
      "    answers = [private_count(true, eps) for _ in range(2000)]\n"
      "    mae = sum(abs(a - true) for a in answers) / len(answers)\n"
      "    print(f'ε = {eps:3}: жауаптың орташа қатесі {mae:6.2f} (теория 1/ε = {1 / eps:.2f})')\n\n"
      "# Бір оқушы қосылса не алынса, жауаптың үлестірімі қаншаға өзгереді?\n"
      "eps = 1.0\n"
      "density = lambda z, c: (eps / 2) * math.exp(-eps * abs(z - c))\n"
      "worst = max(density(z / 10, 37) / density(z / 10, 38) for z in range(200, 600))\n"
      "print(f'тығыздықтар қатынасының ең үлкені: {worst:.4f}, e^ε = {math.exp(eps):.4f}')")

