LLM = ("from math import comb\n\n"
       "def pass_at_k(n, c, k):\n"
       "    \"\"\"n үлгінің c-сы дұрыс; кездейсоқ k үлгінің кемінде біреуі дұрыс болу ықтималдығы (бейтарап баға)\"\"\"\n"
       "    if n - c < k:\n"
       "        return 1.0\n"
       "    return 1 - comb(n - c, k) / comb(n, k)\n\n"
       "results = {'есеп 1': (20, 18), 'есеп 2': (20, 3), 'есеп 3': (20, 0), 'есеп 4': (20, 9)}\n"
       "for k in (1, 5):\n"
       "    avg = sum(pass_at_k(n, c, k) for n, c in results.values()) / len(results)\n"
       "    print(f'pass@{k} = {avg:.3f}')\n\n"
       "# Дереккөзге негізделу: жауаптағы әр сандық тұжырым берілген мәтінде бар ма?\n"
       "source = 'AO17 академиясында 12 модуль және 120 сабақ бар. Senior сатысында 9 модуль.'\n"
       "answer = 'Академияда 12 модуль, 120 сабақ, ал Senior сатысында 10 модуль бар.'\n"
       "import re\n"
       "claims = re.findall(r'\\d+', answer)\n"
       "unsupported = [x for x in claims if x not in re.findall(r'\\d+', source)]\n"
       "print('жауаптағы сандар:', claims, '-> дереккөзде жоқ:', unsupported)")

