AUDIT = ("import math\n\n"
         "audit = {\n"
         "    'әділдік: TPR айырмасы':          {'value': 0.40, 'limit': 0.10, 'n_min': 15},\n"
         "    'тұрақтылық: нәзік шешімдер үлесі': {'value': 0.07, 'limit': 0.10, 'n_min': 550},\n"
         "    'белгісіздік: 90% қамту':          {'value': 0.89, 'limit': 0.88, 'n_min': 2000, 'higher_is_better': True},\n"
         "    'құпиялылық: k-анонимдік':          {'value': 3, 'limit': 5, 'n_min': None, 'higher_is_better': True},\n"
         "    'құжаттама: шектеулер көрсетілген': {'value': 1, 'limit': 1, 'n_min': None, 'higher_is_better': True},\n"
         "}\n\n"
         "def status(c):\n"
         "    hib = c.get('higher_is_better', False)\n"
         "    ok = c['value'] >= c['limit'] if hib else c['value'] <= c['limit']\n"
         "    weak = c['n_min'] is not None and c['n_min'] < 100\n"
         "    return ('ӨТТІ' if ok else 'ӨТПЕДІ') + (' (дерек аз - сенімсіз)' if weak else '')\n\n"
         "fails = 0\n"
         "for name, c in audit.items():\n"
         "    s = status(c)\n"
         "    fails += s.startswith('ӨТПЕДІ')\n"
         "    print(f'{name:36} {c[\"value\"]!s:>5} (шек {c[\"limit\"]}) -> {s}')\n"
         "print('аудит қорытындысы:', 'шығаруға болмайды' if fails else 'шартты түрде мақұлданды', f'({fails} талап орындалмады)')")

